      'CREATE TABLE IF NOT EXISTS "human_request" (\n  "id" TEXT NOT NULL,\n  "created_at" TEXT NOT NULL,\n  "updated_at" TEXT NOT NULL,\n  "author_agent" TEXT,\n  "author_human" TEXT,\n  "version" BIGINT NOT NULL DEFAULT 1,\n  "human_id" TEXT REFERENCES "human" ("id"),\n  "project_id" TEXT REFERENCES "project" ("id"),\n  "task_id" TEXT REFERENCES "task" ("id"),\n  "session_id" TEXT REFERENCES "session" ("id"),\n  "kind" TEXT NOT NULL,\n  "why" TEXT NOT NULL,\n  "steps" JSONB NOT NULL DEFAULT \'[]\',\n  "options" JSONB NOT NULL DEFAULT \'[]\',\n  "blocking" BOOLEAN NOT NULL DEFAULT FALSE,\n  "answer" JSONB,\n  "answered_at" TEXT,\n  "answered_by" TEXT,\n  "status" TEXT NOT NULL DEFAULT \'open\',\n  "risk" TEXT NOT NULL DEFAULT \'low\',\n  "change_card" JSONB,\n  PRIMARY KEY ("id"),\n  CONSTRAINT "human_request_kind_enum" CHECK ("kind" IN (\'decision\', \'credential\', \'approval\', \'info\')),\n  CONSTRAINT "human_request_status_enum" CHECK ("status" IN (\'open\', \'answered\', \'expired\', \'withdrawn\')),\n  CONSTRAINT "human_request_risk_enum" CHECK ("risk" IN (\'low\', \'medium\', \'high\'))\n)',
